#!/usr/bin/env bash
# Upstream absorb report: text conflicts (merge-tree) + semantic overlap
# (files both upstream and local custom commits touched since merge-base).
# Writes .vendor-report.md and, when GITHUB_OUTPUT exists, step outputs.
set -euo pipefail

REPORT=.vendor-report.md
BASE=$(git merge-base main vendor/upstream)
UP_SHORT=$(git rev-parse --short vendor/upstream)
STABLE=$(git describe --tags vendor/stable 2>/dev/null || echo unknown)

CONFLICT_FILES=""
if out=$(git merge-tree --write-tree --name-only main vendor/upstream); then
  HAS_CONFLICTS=false
else
  HAS_CONFLICTS=true
  # First output line is the tree OID; remaining lines mix paths with
  # "Auto-merging"/"CONFLICT" messages — keep only real tracked paths.
  CONFLICT_FILES=$(printf '%s\n' "$out" | tail -n +2 | while IFS= read -r p; do
    if [ -n "$p" ] && { git cat-file -e "vendor/upstream:$p" 2>/dev/null \
                        || git cat-file -e "HEAD:$p" 2>/dev/null; }; then
      printf '%s\n' "$p"
    fi
  done | sort -u)
fi

git diff --name-only "$BASE" vendor/upstream | sort -u > /tmp/vendor-up-changed
git log main --not vendor/upstream --format= --name-only | sed '/^$/d' | sort -u > /tmp/vendor-mine-changed
comm -12 /tmp/vendor-up-changed /tmp/vendor-mine-changed > /tmp/vendor-overlap

UP_COUNT=$(wc -l < /tmp/vendor-up-changed)
MINE_COMMITS=$(git rev-list --count vendor/upstream..main)
OVERLAP_COUNT=$(wc -l < /tmp/vendor-overlap)
PENDING=$(git rev-list --count "$BASE"..vendor/upstream)

{
  echo "# Upstream absorb report"
  echo
  echo "| | |"
  echo "|---|---|"
  echo "| Upstream tip | \`$UP_SHORT\` |"
  echo "| Latest stable tag | \`$STABLE\` |"
  echo "| Last absorbed point | \`$(git rev-parse --short "$BASE")\` |"
  echo "| Unmerged upstream commits | $PENDING |"
  echo "| Your unmerged commits | $MINE_COMMITS |"
  echo "| Files changed upstream | $UP_COUNT |"
  echo "| Files both sides touched | **$OVERLAP_COUNT** |"
  echo "| Text conflicts | $($HAS_CONFLICTS && echo yes || echo no) |"
  echo

  if $HAS_CONFLICTS; then
    echo "## 1. Text conflicts (must resolve before merge)"
    echo
    while IFS= read -r f; do [ -n "$f" ] && echo "- \`$f\`"; done <<< "$CONFLICT_FILES"
    echo
  fi

  echo "## 2. Semantic overlap (review even when the merge is green)"
  echo
  echo "Upstream and your custom commits both modified these files."
  echo "A clean text merge can still break behavior; inspect each one."
  echo
  if [ "$OVERLAP_COUNT" -eq 0 ]; then
    echo "_None._"
  else
    head -40 /tmp/vendor-overlap | while IFS= read -r f; do
      echo "- \`$f\`"
      git log --oneline -n 3 "vendor/upstream...main" -- "$f" | sed 's/^/  - /'
    done
    [ "$OVERLAP_COUNT" -gt 40 ] && echo "- …and $((OVERLAP_COUNT - 40)) more"
  fi
  echo

  echo "## 3. Your custom commits not yet upstream (max 50)"
  echo
  echo '```'
  git log --oneline -n 50 vendor/upstream..main
  echo '```'
  echo
  echo "_Generated by vendor-sync. Resolve section 1, review section 2, then merge vendor/upstream into main._"
} > "$REPORT"

echo "report written: $REPORT"
if [ -n "${GITHUB_OUTPUT:-}" ]; then
  echo "has_conflicts=$HAS_CONFLICTS" >> "$GITHUB_OUTPUT"
  echo "overlap=$OVERLAP_COUNT" >> "$GITHUB_OUTPUT"
fi
